/**
 * ============================================
 * BFE.dev Promise 系列题解 —— 简化易懂版
 * ============================================
 * 目标:每一段都能看懂"为什么这么写",不追求100%符合规范细节
 */


// ============================================
// 67. 手写一个Promise (Create your own Promise)
// ============================================
/**
 * 核心思路:
 * 1. Promise本质是个"状态机": pending → fulfilled 或 pending → rejected,且状态只能变一次
 * 2. then() 可能在状态还没确定时就被调用,所以要把回调"存起来",等状态确定了再执行
 * 3. then() 必须异步执行(哪怕结果已经有了),这里用 queueMicrotask 模拟微任务
 */
class MyPromise {
  constructor(executor) {
    this.state = 'pending'; // pending / fulfilled / rejected
    this.value = undefined;
    this.callbacks = []; // 存放"还没来得及执行"的 then 回调

    const resolve = (value) => {
      // 支持 resolve(另一个Promise) 的情况:等它完成后再决定我的状态
      if (value instanceof MyPromise) {
        value.then(resolve, reject);
        return;
      }
      if (this.state !== 'pending') return; // 状态锁定,只能变一次
      this.state = 'fulfilled';
      this.value = value;
      this.callbacks.forEach(cb => cb.onFulfilled(value));
    };

    const reject = (reason) => {
      if (this.state !== 'pending') return;
      this.state = 'rejected';
      this.value = reason;
      this.callbacks.forEach(cb => cb.onRejected(reason));
    };

    try {
      executor(resolve, reject);
    } catch (err) {
      reject(err); // executor同步执行时报错,也要能被reject捕获
    }
  }

  then(onFulfilled, onRejected) {
    // 参数不是函数时的默认行为:直接把值/错误往下传
    onFulfilled = typeof onFulfilled === 'function' ? onFulfilled : v => v;
    onRejected = typeof onRejected === 'function' ? onRejected : err => { throw err; };

    return new MyPromise((resolve, reject) => {
      const handleFulfilled = (value) => {
        queueMicrotask(() => { // 强制异步,保证执行顺序可预测
          try {
            resolve(onFulfilled(value)); // 支持链式调用,把返回值传给下一个then
          } catch (err) {
            reject(err);
          }
        });
      };

      const handleRejected = (reason) => {
        queueMicrotask(() => {
          try {
            resolve(onRejected(reason)); // 注意:catch住的错误如果没再抛,链会"恢复成功"
          } catch (err) {
            reject(err);
          }
        });
      };

      if (this.state === 'fulfilled') handleFulfilled(this.value);
      else if (this.state === 'rejected') handleRejected(this.value);
      else this.callbacks.push({ onFulfilled: handleFulfilled, onRejected: handleRejected }); // 还没决定,先存起来
    });
  }

  catch(onRejected) {
    return this.then(null, onRejected);
  }
}


// ============================================
// 123. 实现 Promise.prototype.finally()
// ============================================
/**
 * 核心难点:finally的回调"不接收参数",而且不管成功失败都要"原样传递"结果
 * 也就是说 finally 不能改变最终的成功值/失败原因,只是"顺便执行一下"
 */
MyPromise.prototype.finally = function (callback) {
  return this.then(
    (value) => {
      callback(); // 成功时,先执行callback,再把原来的value原样传下去
      return value;
    },
    (reason) => {
      callback(); // 失败时同理,执行完callback,继续把原来的reason原样抛出去
      throw reason;
    }
  );
};


// ============================================
// 32. 实现 Promise.all()
// ============================================
/**
 * 核心思路:
 * - 全部成功才成功,结果按"传入顺序"放进数组返回(不是谁先完成谁排前面!)
 * - 只要有一个失败,立刻整体reject
 */
function myPromiseAll(promises) {
  return new MyPromise((resolve, reject) => {
    const results = [];
    let completedCount = 0;

    if (promises.length === 0) {
      resolve([]);
      return;
    }

    promises.forEach((p, index) => {
      // 用Promise.resolve包一层,这样即使传进来的不是Promise(是普通值),也能统一处理
      MyPromise.resolve(p).then(
        (value) => {
          results[index] = value; // 按index存,保证顺序和传入时一致
          completedCount++;
          if (completedCount === promises.length) {
            resolve(results);
          }
        },
        (err) => reject(err) // 任何一个失败,立刻整体失败
      );
    });
  });
}


// ============================================
// 33. 实现 Promise.allSettled()
// ============================================
/**
 * 和 all 的区别:不管成功失败,都要等所有Promise跑完,而且每个都要返回详细状态
 * 不会因为某一个失败就提前结束(这是和all最大的区别)
 */
function myPromiseAllSettled(promises) {
  return new MyPromise((resolve) => {
    const results = [];
    let completedCount = 0;

    if (promises.length === 0) {
      resolve([]);
      return;
    }

    promises.forEach((p, index) => {
      MyPromise.resolve(p).then(
        (value) => {
          results[index] = { status: 'fulfilled', value };
          completedCount++;
          if (completedCount === promises.length) resolve(results);
        },
        (reason) => {
          results[index] = { status: 'rejected', reason }; // 失败也照样记录,不reject整体
          completedCount++;
          if (completedCount === promises.length) resolve(results);
        }
      );
    });
  });
}


// ============================================
// 35. 实现 Promise.race()
// ============================================
/**
 * 最简单的一个:谁先有结果(不管成功失败),就用谁的
 */
function myPromiseRace(promises) {
  return new MyPromise((resolve, reject) => {
    promises.forEach((p) => {
      MyPromise.resolve(p).then(resolve, reject); // 直接把resolve/reject传进去,谁先调用算谁的
    });
  });
}


// ============================================
// 34. 实现 Promise.any()
// ============================================
/**
 * 和all正好相反的思路:只要有一个成功就整体成功
 * 只有"全部都失败"才会reject,而且要把所有失败原因收集起来(AggregateError)
 */
function myPromiseAny(promises) {
  return new MyPromise((resolve, reject) => {
    const errors = [];
    let rejectedCount = 0;

    if (promises.length === 0) {
      reject(new Error('All promises were rejected'));
      return;
    }

    promises.forEach((p, index) => {
      MyPromise.resolve(p).then(
        (value) => resolve(value), // 只要有一个成功,立刻整体成功
        (err) => {
          errors[index] = err;
          rejectedCount++;
          if (rejectedCount === promises.length) {
            // 全部失败才reject,原生API这里会抛AggregateError,这里简化用普通Error+errors数组
            reject(new Error('All promises were rejected: ' + JSON.stringify(errors)));
          }
        }
      );
    });
  });
}


// 补一下 MyPromise.resolve,上面几个实现里用到了
MyPromise.resolve = function (value) {
  if (value instanceof MyPromise) return value; // 已经是Promise就直接返回,不用再包一层
  return new MyPromise((resolve) => resolve(value));
};
MyPromise.reject = function (reason) {
  return new MyPromise((resolve, reject) => reject(reason));
};


// ============================================
// 64. Promise失败自动重试 (auto-retry on rejection)
// ============================================
/**
 * 场景:调用一个可能失败的异步函数,失败了自动重试,重试次数用完还失败才真正报错
 * 核心思路:用递归 —— 失败了就再调用一次自己,直到成功或次数用完
 */
function retry(fn, times) {
  return new Promise((resolve, reject) => {
    function attempt(remainingTimes) {
      fn()
        .then(resolve) // 成功了直接resolve,不用再试了
        .catch((err) => {
          if (remainingTimes <= 0) {
            reject(err); // 次数用完了,真的失败,把最后一次的错误抛出去
          } else {
            attempt(remainingTimes - 1); // 还有次数,再试一次
          }
        });
    }
    attempt(times);
  });
}

/**
 * 使用示例:
 *
 * let count = 0;
 * function mayFail() {
 *   return new Promise((resolve, reject) => {
 *     count++;
 *     if (count < 3) reject('failed attempt ' + count);
 *     else resolve('success on attempt ' + count);
 *   });
 * }
 *
 * retry(mayFail, 5).then(console.log); // 重试2次后,第3次成功: "success on attempt 3"
 */


// ============================================
// 92. Throttle Promises (限流:同一时间最多跑N个)
// ============================================
/**
 * 场景:你有100个异步任务(比如100个网络请求),但不想100个同时发出去把服务器打爆,
 * 而是"同一时刻最多跑max个,跑完一个再补一个上去",直到全部跑完
 *
 * 核心思路:
 * 1. 维护一个"正在运行中的任务数量"计数器
 * 2. 每次有任务完成,就检查还有没有排队的任务,有的话立刻补上一个新的开始跑
 */
class PromisePool {
  constructor(max) {
    this.max = max; // 同时最多跑几个
    this.running = 0; // 当前正在跑的数量
    this.queue = []; // 排队等待执行的任务
  }

  add(promiseCreator) {
    // promiseCreator 是一个"返回Promise的函数",而不是Promise本身
    // 这一点很重要!因为Promise一旦创建就立刻开始执行了,
    // 我们需要"延迟到轮到它的时候才真正开始跑",所以必须传函数,而不是已经在跑的Promise
    return new Promise((resolve, reject) => {
      const task = () => {
        this.running++;
        promiseCreator()
          .then((result) => {
            resolve(result);
            this._next();
          })
          .catch((err) => {
            reject(err);
            this._next();
          });
      };

      if (this.running < this.max) {
        task(); // 还没到上限,立刻跑
      } else {
        this.queue.push(task); // 到上限了,先排队
      }
    });
  }

  _next() {
    this.running--;
    if (this.queue.length > 0) {
      const nextTask = this.queue.shift();
      nextTask(); // 有任务在排队,立刻补上一个开始跑
    }
  }
}

/**
 * 使用示例: 同一时刻最多跑2个任务
 *
 * const pool = new PromisePool(2);
 * function createTask(id, delay) {
 *   return () => new Promise(resolve => {
 *     console.log('开始任务', id);
 *     setTimeout(() => {
 *       console.log('完成任务', id);
 *       resolve(id);
 *     }, delay);
 *   });
 * }
 *
 * pool.add(createTask(1, 1000));
 * pool.add(createTask(2, 1000));
 * pool.add(createTask(3, 1000)); // 会等1或2完成后才开始跑
 * pool.add(createTask(4, 1000));
 */


module.exports = {
  MyPromise,
  myPromiseAll,
  myPromiseAllSettled,
  myPromiseRace,
  myPromiseAny,
  retry,
  PromisePool,
};
